"""Convert us-atlas states-albers-10m.json (TopoJSON) into site/vendor/us-states-albers.js.

Stdlib only and network-free. Usage:

    uv run python -I ops/vendor/us_states_albers.py <source.json> <out.js>

Decodes ``objects.states`` (quantized or not), drops Alaska (FIPS 02, D-14), rounds
coordinates to 0.1 map unit, and writes a deterministic ES module.
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

WIDTH = 975
HEIGHT = 610
EXPECTED_FEATURES = 50
DROPPED_IDS = frozenset({"02"})

HEADER = """/*
 * Generated by ops/vendor/us_states_albers.py from us-atlas 3.0.1
 * states-albers-10m.json. Do not edit by hand.
 * Contains US Census Bureau cartographic boundary data via us-atlas (ISC).
 * State outlines only, pre-projected to a 975x610 Albers USA space (Hawaii in its
 * inset); Alaska is not included. Coordinates rounded to 0.1 map unit.
 *
 * us-atlas license (ISC):
 *
 * Copyright 2013-2019 Michael Bostock
 *
 * Permission to use, copy, modify, and/or distribute this software for any purpose
 * with or without fee is hereby granted, provided that the above copyright notice
 * and this permission notice appear in all copies.
 *
 * THE SOFTWARE IS PROVIDED "AS IS" AND THE AUTHOR DISCLAIMS ALL WARRANTIES WITH
 * REGARD TO THIS SOFTWARE INCLUDING ALL IMPLIED WARRANTIES OF MERCHANTABILITY AND
 * FITNESS. IN NO EVENT SHALL THE AUTHOR BE LIABLE FOR ANY SPECIAL, DIRECT,
 * INDIRECT, OR CONSEQUENTIAL DAMAGES OR ANY DAMAGES WHATSOEVER RESULTING FROM LOSS
 * OF USE, DATA OR PROFITS, WHETHER IN AN ACTION OF CONTRACT, NEGLIGENCE OR OTHER
 * TORTIOUS ACTION, ARISING OUT OF OR IN CONNECTION WITH THE USE OR PERFORMANCE OF
 * THIS SOFTWARE.
 */
"""

Point = tuple[float, float]


def decode_arcs(topology: dict[str, Any]) -> list[list[Point]]:
    """Return every arc as absolute (x, y) points in map units."""
    transform = topology.get("transform")
    arcs: list[list[Point]] = []
    for raw in topology["arcs"]:
        points: list[Point] = []
        qx = qy = 0.0
        for i, (dx, dy) in enumerate(raw):
            if transform is not None:
                qx = dx if i == 0 else qx + dx
                qy = dy if i == 0 else qy + dy
                x = qx * transform["scale"][0] + transform["translate"][0]
                y = qy * transform["scale"][1] + transform["translate"][1]
            else:
                x, y = dx, dy
            points.append((x, y))
        arcs.append(points)
    return arcs


def ring_points(arc_indexes: list[int], arcs: list[list[Point]]) -> list[Point]:
    ring: list[Point] = []
    for n, a in enumerate(arc_indexes):
        pts = arcs[a] if a >= 0 else arcs[~a][::-1]
        ring.extend(pts if n == 0 else pts[1:])
    return ring


def geometry_rings(geometry: dict[str, Any], arcs: list[list[Point]]) -> list[list[Point]]:
    kind = geometry["type"]
    if kind == "Polygon":
        polygons = [geometry["arcs"]]
    elif kind == "MultiPolygon":
        polygons = geometry["arcs"]
    else:
        raise SystemExit(f"unsupported geometry type {kind!r}")
    return [ring_points(ring, arcs) for polygon in polygons for ring in polygon]


def fmt(value: float) -> str:
    text = f"{value:.1f}"
    return text[:-2] if text.endswith(".0") else text


def flatten(ring: list[Point]) -> list[str]:
    rounded: list[Point] = []
    for x, y in ring:
        point = (round(x, 1), round(y, 1))
        if not rounded or rounded[-1] != point:
            rounded.append(point)
    out: list[str] = []
    for x, y in rounded:
        if not (0 <= x <= WIDTH and 0 <= y <= HEIGHT):
            raise SystemExit(f"coordinate ({x}, {y}) outside 0..{WIDTH} x 0..{HEIGHT}")
        out.extend((fmt(x), fmt(y)))
    return out


def build_module(topology: dict[str, Any]) -> str:
    arcs = decode_arcs(topology)
    features = [
        g for g in topology["objects"]["states"]["geometries"] if str(g["id"]) not in DROPPED_IDS
    ]
    features.sort(key=lambda g: str(g["id"]))
    if len(features) != EXPECTED_FEATURES:
        raise SystemExit(f"expected {EXPECTED_FEATURES} features, got {len(features)}")
    lines: list[str] = []
    for geometry in features:
        fid = str(geometry["id"])
        rings = [flatten(r) for r in geometry_rings(geometry, arcs)]
        if fid == "15" and not rings:
            raise SystemExit("Hawaii (15) has no ring")
        body = ", ".join("[" + ", ".join(r) + "]" for r in rings)
        lines.append(f"  {{ id: '{fid}', rings: [{body}] }},")
    if not any("id: '15'" in line for line in lines):
        raise SystemExit("Hawaii (15) missing")
    return HEADER + "\nexport const US_STATES = Object.freeze([\n" + "\n".join(lines) + "\n]);\n"


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("source", type=Path)
    parser.add_argument("out", type=Path)
    args = parser.parse_args(argv)
    topology = json.loads(args.source.read_text(encoding="utf-8"))
    module = build_module(topology)
    with args.out.open("w", encoding="utf-8", newline="\n") as handle:
        handle.write(module)
    return 0


if __name__ == "__main__":
    sys.exit(main())
